{{ config(materialized='table') }}

with
quarantined as (
    select
        company_external_lookup_key,
        company_business_key,
        company_entity_count,
        violation_00,
        violation_01,
        violation_02
    from {{ ref("investment__company_external_index__checked_post") }}
),
violations as (
    select
        'company_external_lookup_key_not_null' as rule_name,
        company_external_lookup_key,
        company_business_key,
        company_entity_count
    from quarantined
    where violation_00

    union all

    select
        'company_external_lookup_key_unique' as rule_name,
        company_external_lookup_key,
        company_business_key,
        company_entity_count
    from quarantined
    where violation_01

    union all

    select
        'company_entity_count_range' as rule_name,
        company_external_lookup_key,
        company_business_key,
        company_entity_count
    from quarantined
    where violation_02
)

select
    rule_name,
    company_external_lookup_key,
    company_business_key,
    company_entity_count
from violations
